# Architecture decisions use common comparison criteria, generic options rather than unsupported capabilities.
def arch(i,t,cat,choice,alts,tr,perm,blast,ap,least,ts):
 return add('framework',i,'framework',t,choice,'Choose durable deterministic control for money and long human waits; vendors remain candidates needing proof.',dict(category=cat,taskIds=ts,choice=choice,alternatives=alts,tradeoffs=tr,permission=perm,blastRadius=blast,approvalRule=ap,leastPrivilege=least,aws='Unverified candidate: managed workflow/queue + relational ledger/object evidence; verify timers, transactions, residency and operation lookup.',gcp='Unverified candidate: workflow/queue + relational ledger/object evidence; verify identical timers, transactions, residency and operation lookup.',azure='Unverified candidate: durable workflow/queue + relational ledger/object evidence; verify identical timers, transactions, residency and operation lookup.',openSource='Candidate: durable job engine + PostgreSQL ledger/outbox and encrypted object evidence; team owns backups, scheduler recovery and upgrades.'),('H3','H5'))
arch('F1','Bounded agent inside durable workflow','architecture','Code-owned case state machine W1-W17 with one sandboxed C3 judgement step. Persist case, operation and event state outside model context.','', 'One model keeps explanation coherent; durable scheduler adds operational burden but supports 48h waits and unknown commits. No model has action tools.','none','C3 can affect draft only; code contains money risk.','No framework/model can supply financial authority.','Separate investigator role from action adapter and queue roles.',['T0'])['data']['alternatives']=['Rejected autonomous multi-agent refund crew: duplicated judgement/state cannot replace ledger transactions; larger tool exposure and hard-to-bound recovery.','Rejected synchronous chatbot-only implementation: session loss would abandon supervisor timers and uncertain credits.']
arch('F2','Orchestration selection','orchestration','Use a durable worker/SQL outbox with explicit states for v1; evaluate a managed workflow engine if scheduler reliability/capacity exceeds team capability.',['Durable workflow framework candidate: compare replay determinism, timer recovery, transaction boundaries, operational ownership and migration cost; unverified until spike.','In-memory graph orchestration rejected: graph routing alone does not establish durable waits or action idempotency.'],'Same criteria: persistence under crash, timer recovery, version upgrades, audit replay, ownership cost. Simple code workflow minimizes framework dependency; operating timers is a real obligation.','none','All cases if scheduler fails; ledger uniqueness still prevents duplicate funds.','Expansion requires operations lead release gate.','Worker roles only receive state-specific commands.',['T5','T4.2'])
arch('F3','Action permissions and blast radius','permission','Read roles scope to tenant/customer/connection; writer scope to one immutable credit; supervisor may authorize a policy-permitted larger amount but cannot override subject/active/duplicate controls.',['Rejected account-wide service token in model context; leakage would expose unrelated customers.'],'Fresh authority at API raises latency; required to prevent revoked or stale approvals.','write','One incident invoice-line credit; global kill switch disables new dispatch without disabling lookup.','Customer confirms exact amount/digest; policy service signs auto authority or supervisor signs immutable payload.','Credentials held only by adapters; recon role read-only; separate notification role; no cash refund/reversal credentials.',['T1','T4.1','T4.2','T5'])
arch('F4','Evidence versus authoritative financial state','data','Relational case/operation/approval/outbox records; encrypted evidence objects addressed by ID/version; financial ledger remains authoritative. Retrieval index, if later added, cannot decide ownership or balances.',['Rejected vector search as financial system of record: approximate retrieval cannot enforce uniqueness or current ownership.'],'Case snapshots aid audit but increase privacy surface; minimize fields and apply H5 retention with financial legal holds only after privacy approval.','read','Relevant invoice and incident only; no whole-account exports.','Approved adapters enforce scope before loading and before posting.','Encrypt at rest/in transit, tenant keys/row filters, secret vault, redacted logs; audit access plus transitions and policy digests.',['T2','T3','T4.1','T5'])
arch('F5','Recovery and ownership boundary','fit','No real adapters are assumed proven. H3 sandbox spike is launch blocker; if atomic uniqueness or authoritative unknown lookup is unavailable, ship assist-only investigation and human credit processing.',['Rejected client-side retry around non-idempotent billing API: timeout could duplicate credit.'],'Assist-only sacrifices automation benefit while preserving useful investigation; no claim of production readiness.','none','Uncertain operation freezes same incident credit across all sessions until resolved.','Finance lead accepts operating process and residual risk explicitly before pilot; no acceptance claimed here.','Persistent recon service identity survives customer session expiry without new write rights.',['T4.1','T4.2','T5'])
add('models','M1','model','Single investigator budget','C3 called once at W3, with at most one schema retry; evidence insufficiency at W2 bypasses it. H6: 80% reach W3, 10% of those retry -> 0.8*(1+0.1)=0.88 calls/intake; worst case 2. Each call illustrative 4000 input and 600 output tokens; $2/$8 per million => $0.0128/call; $0.011264/intake, $112.64/10000 intakes; worst $0.0256/intake. W13/W14/W15/W16/W17 use templates, no extra LLM calls.','Standard tier proposed for evidence citation and plain language. Small tier rejected until contradiction/citation parity; reasoning tier rejected absent measured benefit on bounded task. Compare all on goldens, abstention, latency p95 10s/call and token cost. 4000-token input cap truncates by excluding irrelevant records, never partial financial records; oversized packet routes human.',dict(componentId='C3',tier='standard',rationale='Illustrative budget above; unknown vendor prices. One schema retry only; unavailable/invalid -> C5. Prices exclude tools, hosting, storage, human review, notifications and evaluation; peak load unknown and must be measured.',fineTuneWhen='Only after recurring adjudicated evidence/citation failure persists after prompt and packet changes; require held-out quality and safety non-regression plus lower total cost than prompting baseline. Never fine-tune to bypass code guards.',callsPerCase=0.88,inputTokens=4000,outputTokens=600,inputPrice=2,outputPrice=8),('H6',))

